class Solution {
  public int countOfPairs(int[] nums) {
    final int MOD = 1_000_000_007;
    int n = nums.length, max = 0;
    for (int x : nums) max = Math.max(max, x);
    // dp[a]: ways with arr1[i] = a (arr2[i] = nums[i] - a)
    long[] dp = new long[max + 1];
    for (int a = 0; a <= nums[0]; a++) dp[a] = 1;
    for (int i = 1; i < n; i++) {
      long[] prefix = new long[max + 1];
      prefix[0] = dp[0];
      for (int a = 1; a <= max; a++) prefix[a] = (prefix[a - 1] + dp[a]) % MOD;
      int rise = Math.max(0, nums[i] - nums[i - 1]);
      long[] next = new long[max + 1];
      for (int a = rise; a <= nums[i]; a++) {
        int previous = Math.min(a - rise, nums[i - 1]);
        next[a] = prefix[previous];
      }
      dp = next;
    }
    long total = 0;
    for (long v : dp) total = (total + v) % MOD;
    return (int) total;
  }
}
